        try c.sendMoney(target, sendAmount) {} catch {}

        // Owner now calls withdrawAll.
        vm.prank(c.owner());
        c.withdrawAll();

        // 3. Assertion: After withdrawAll, the contract's ETH balance must be zero.
        // Reference: withdrawAll internally calls withdraw(address(this).balance) clearing the balance.
        // Buggy: withdrawAll does nothing, leaving the balance untouched (and non-zero).
        assertTrue(address(c).balance == 0);
    }
