import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        address owner = c.owner();
        uint256 balBefore = owner.balance;
        vm.prank(owner);
        c.withdraw(amount);
        uint256 balAfter = owner.balance;
        assertTrue(balBefore == balAfter);
    }
}

